require __DIR__.'/app/bootstrap.php';$ctx=growth_seller_context('products');$u=$ctx['user'];$seller=(int)$ctx['owner_id'];$msg=$err=null;$products=operations_rows('SELECT * FROM store_products WHERE seller_user_id=? ORDER BY id DESC',[$seller]);
if($_SERVER['REQUEST_METHOD']==='POST')try{csrf_check();$a=$_POST['action']??'';if($a==='move'){inventory_move($seller,(int)$_POST['product_id'],(int)$_POST['quantity'],(string)$_POST['movement_type'],!empty($_POST['variant_id'])?(int)$_POST['variant_id']:null,null,'seller_adjustment',null,trim((string)($_POST['note']??'')),(int)$u['id']);$msg='Inventory updated.';}elseif($a==='variant'){inventory_save_variant($seller,(int)$_POST['product_id'],(string)$_POST['variant_name'],(string)($_POST['sku']??''),(string)($_POST['barcode']??''),(float)($_POST['price_adjustment']??0));$msg='Variant created.';}}catch(Throwable $e){$err=$e->getMessage();}
$products=operations_rows('SELECT * FROM store_products WHERE seller_user_id=? ORDER BY id DESC',[$seller]);$variants=operations_rows('SELECT v.*,p.title FROM product_variants v JOIN store_products p ON p.id=v.product_id WHERE p.seller_user_id=? ORDER BY v.id DESC',[$seller]);$moves=operations_rows('SELECT m.*,p.title FROM inventory_movements m JOIN store_products p ON p.id=m.product_id WHERE m.seller_user_id=? ORDER BY m.id DESC LIMIT 100',[$seller]);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seller Inventory</title><link rel="stylesheet" href="/assets/shahkotpk-userdash-1.7.0.css"><link rel="stylesheet" href="/assets/operations-3.6.0.css"></head><body class="dashboard-page"><div class="dash-shell"><div class="dash-topbar"><a class="dash-back" href="/shopkeeper.php">← Seller Dashboard</a><div class="dash-actions"><a class="dash-chip" href="/shopkeeper-products.php">Products</a><a class="dash-chip" href="/seller-finance.php">Finance</a></div></div><section class="dash-hero"><div><span class="dash-badge">INVENTORY CONTROL</span><h1>Stock, SKU & Barcode</h1><p>Manage stock movements and product variants from the seller center.</p></div></section><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><div class="ops-grid"><section class="ops-card"><h2>Stock Movement</h2><form method="post" class="ops-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="move"><select name="product_id" required><option value="">Product</option><?php foreach($products as $p):?><option value="<?=e($p['id'])?>"><?=e($p['title'].' — Stock '.$p['stock'])?></option><?php endforeach;?></select><select name="movement_type"><option>adjustment_in</option><option>adjustment_out</option><option>damage</option><option>return_in</option><option>return_out</option></select><input name="quantity" type="number" min="1" value="1"><input name="note" placeholder="Reason"><button class="btn">Update Stock</button></form></section><section class="ops-card"><h2>Add Variant / SKU</h2><form method="post" class="ops-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="variant"><select name="product_id" required><option value="">Product</option><?php foreach($products as $p):?><option value="<?=e($p['id'])?>"><?=e($p['title'])?></option><?php endforeach;?></select><input name="variant_name" placeholder="Variant" required><input name="sku" placeholder="SKU"><input name="barcode" placeholder="Barcode"><input name="price_adjustment" type="number" step="0.01" placeholder="Price adjustment"><button class="btn">Create Variant</button></form></section></div><section class="dash-card"><h2>Variants</h2><div class="ops-table"><table><tr><th>Product</th><th>Variant</th><th>SKU</th><th>Barcode</th><th>Stock</th></tr><?php foreach($variants as $v):?><tr><td><?=e($v['title'])?></td><td><?=e($v['variant_name'])?></td><td><?=e($v['sku'])?></td><td><?=e($v['barcode'])?></td><td><?=e($v['stock'])?></td></tr><?php endforeach;?></table></div></section><section class="dash-card"><h2>Movement History</h2><div class="ops-table"><table><tr><th>Date</th><th>Product</th><th>Type</th><th>Qty</th><th>Note</th></tr><?php foreach($moves as $m):?><tr><td><?=e($m['created_at'])?></td><td><?=e($m['title'])?></td><td><?=e($m['movement_type'])?></td><td><?=e($m['quantity'])?></td><td><?=e($m['note'])?></td></tr><?php endforeach;?></table></div></section></div></body></html>
